// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['weather'], 'Utility', 'Check the weather for a city', async ({ sock, from, msg, args }) => {
  const city = args.join(' ');
  if (!city) return sock.sendMessage(from, { text: 'Usage: .weather Lagos' }, { quoted: msg });
  try {
    const geo = await (await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}`)).json();
    const loc = geo.results?.[0];
    if (!loc) return sock.sendMessage(from, { text: 'City not found.' }, { quoted: msg });
    const w = await (await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${loc.latitude}&longitude=${loc.longitude}&current_weather=true`)).json();
    await sock.sendMessage(from, { text: `⛅ *${loc.name}, ${loc.country}*\nTemp: ${w.current_weather.temperature}°C\nWind: ${w.current_weather.windspeed} km/h` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Weather service unavailable.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
